  const updateBannerReport=async(id:number,status:string)=>{setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/reports/"+id,token,{method:"PATCH",body:JSON.stringify({status})});await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_report_update_failed")}finally{setBusy(false)}};
   const exportBannerUserHistory=async()=>{if(!bannerUserId.trim())return;try{const res=await fetch(API+"/api/v1/admin/ecosystem/banner/users/"+encodeURIComponent(bannerUserId.trim())+"/export?format=csv",{headers:{authorization:"Bearer "+token}});if(!res.ok)throw new Error("export_failed");const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="an-banner-user-history.csv";a.click();URL.revokeObjectURL(url)}catch(e){setError(e instanceof Error?e.message:"export_failed")}};
   const editBannerTemplate=async(t:any)=>{const title=window.prompt("عنوان پیام",t.title);if(title===null)return;const body=window.prompt("متن پیام",t.body);if(body===null)return;setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/templates/"+t.id,token,{method:"PATCH",body:JSON.stringify({title,body,restrictionCode:t.restriction_code,durationHours:t.duration_hours,active:t.active})});await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_template_update_failed")}finally{setBusy(false)}};
   const sendBannerUserMessage=async(templateId?:number)=>{if(!bannerUserId.trim())return;const template=templateId?bannerTemplates.find(x=>x.id===templateId):null;const body=template?{templateId}:{};setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/users/"+encodeURIComponent(bannerUserId.trim())+"/message",token,{method:"POST",body:JSON.stringify(body)});await loadBannerUser();await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_message_failed")}finally{setBusy(false)}};
   const restrictBannerUser=async(code:string)=>{if(!bannerUserId.trim())return;const reason=window.prompt("دلیل محدودیت");if(reason===null)return;setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/users/"+encodeURIComponent(bannerUserId.trim())+"/restrict",token,{method:"POST",body:JSON.stringify({restrictionCode:code,reason,durationHours:24})});await loadBannerUser();await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_restrict_failed")}finally{setBusy(false)}};
   const unrestrictBannerUser=async()=>{if(!bannerUserId.trim())return;setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/users/"+encodeURIComponent(bannerUserId.trim())+"/unrestrict",token,{method:"POST",body:JSON.stringify({})});await loadBannerUser();await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_unrestrict_failed")}finally{setBusy(false)}};
   const banBannerUser=async()=>{if(!bannerUserId.trim())return;const reason=window.prompt("دلیل مسدودسازی دائمی");if(reason===null)return;setBusy(true);try{await api("/api/v1/admin/ecosystem/banner/users/"+encodeURIComponent(bannerUserId.trim())+"/ban",token,{method:"POST",body:JSON.stringify({reason})});await loadBannerUser();await loadBanner()}catch(e){setError(e instanceof Error?e.message:"banner_ban_failed")}finally{setBusy(false)}};
